shader_type canvas_item;
render_mode unshaded;

uniform float warning : hint_range(0.0, 1.0) = 0.0;
uniform vec4 warn_color : source_color = vec4(1.0, 0.702, 0.278, 1.0);
uniform float strength : hint_range(0.0, 1.0) = 0.65;

void fragment() {
    COLOR.rgb = mix(COLOR.rgb, warn_color.rgb, warning * strength);
}

func warning() -> float:
	## Shader `warning` (CHANGE-BRIEF.md §2): the shadow growth during SHADOW; 0 in other phases or when held.
	if held or phase() != Phase.SHADOW:
		return 0.0
	return shadow_amount()

func _apply() -> void:
	if head:
		head.position.y = tip_y()
	if sprite:
		sprite.material.set_shader_parameter("warning", warning())

func expected_at(i: int, pos: int) -> float:
	## The brief's formula (§2) at cycle position pos: (p - safe + 1) / shadow in SHADOW, else 0.
	var c := cycle_of(i)
	var p := posmod(pos, c.period)
	if p >= c.safe and p < c.safe + c.shadow:
		return float(p - c.safe + 1) / float(c.shadow)
	return 0.0

uniform sampler2D strip_as_colour : source_color, filter_nearest;
uniform sampler2D strip_as_data : filter_nearest;

uniform bool use_source_color = true;

void fragment() {
    if (use_source_color) {
        ALBEDO = texture(strip_as_colour, UV).rgb;
    } else {
        ALBEDO = texture(strip_as_data, UV).rgb;
    }
}

group_uniforms colour;

uniform sampler2D albedo_tex : source_color, filter_linear_mipmap, repeat_enable;
uniform vec4 tint : source_color = vec4(1.0, 1.0, 1.0, 1.0);
uniform float brightness : hint_range(0.0, 2.0) = 1.0;

group_uniforms surface;

uniform sampler2D roughness_tex : hint_default_white, filter_linear_mipmap, repeat_enable;
uniform sampler2D normal_tex : hint_normal, filter_linear_mipmap, repeat_enable;
uniform float roughness_scale : hint_range(0.0, 1.0) = 1.0;
uniform float normal_strength : hint_range(0.0, 2.0) = 1.0;
